mapper.select:
SELECT d.*, dt.name as type_name, ic.name as industry_chain_name FROM dataset d LEFT JOIN dict_dataset_type dt ON d.type_code = dt.code LEFT JOIN industry_chain ic ON d.industry_chain_id = ic.id
AND d.name LIKE CONCAT('%', #{query.name}, '%')
AND d.type_code = #{query.typeCode}
AND d.industry_chain_id = #{query.industryChainId}
AND d.deleted = 0
ORDER BY d.data_period DESC
